# Role-based access and masking for the Credit Lookup agent. Everything here
# runs in plain Python BEFORE any LLM sees the data: fields a role may not see
# are dropped, national ID and phone are masked, and late-payment facts are
# computed deterministically -- so neither the model nor the person asking
# can get more than the role allows, and no number is ever generated by a
# model. Rules follow the demo policy 《個人資料處理作業規範》 第3–4條
# (data/regulations/policies/): sales staff see customer basics and contract
# status only; payment detail and risk assessment are for credit staff; IDs
# show the first character and the last three digits.
from datetime import date

from finance.loan_calc import (
    PREPAYMENT_FEE_SOURCE,
    months_between,
    payoff_quote,
    prepayment_fee_rate,
    remaining_balance,
)
from finance.plans import product_method

ROLES = {"sales": "業務", "credit": "授信"}

DISCLAIMER = "本摘要僅供參考，不構成授信核准或拒絕之決定，相關決定應由權責人員依授信準則判斷。"


def is_valid_caller(caller: dict | None) -> bool:

    return bool(caller) and caller.get("role") in ROLES and bool(str(caller.get("user_id", "")).strip())


def mask_national_id(national_id: str) -> str:

    """A123456789 -> A******789"""

    if len(national_id) < 4:
        return "*" * len(national_id)
    return national_id[0] + "*" * (len(national_id) - 4) + national_id[-3:]


def mask_phone(phone: str) -> str:

    """0912345678 -> 0912-***-678"""

    digits = "".join(ch for ch in phone if ch.isdigit())
    if len(digits) < 7:
        return "*" * len(digits)
    return f"{digits[:4]}-***-{digits[-3:]}"


def compute_late_facts(payments: list[dict], as_of: date) -> dict:

    """Late-payment facts over the given payment rows (already limited to the
    lookup window by the caller)."""

    late = [p for p in payments if p["days_late"] > 0]
    unpaid = [p for p in payments if p["paid_date"] is None and date.fromisoformat(p["due_date"]) <= as_of]
    return {
        "late_count": len(late),
        "max_days_late": max((p["days_late"] for p in late), default=0),
        "currently_overdue": bool(unpaid),
        "overdue_days": max(((as_of - date.fromisoformat(p["due_date"])).days for p in unpaid), default=0),
        "late_periods": [
            {"contract_id": p["contract_id"], "period": p["period"], "due_date": p["due_date"],
             "days_late": p["days_late"], "paid": p["paid_date"] is not None}
            for p in late
        ],
    }


def build_payoff(contract: dict, as_of: date, role: str) -> dict:

    """提前清償試算 for one active contract, computed by finance/loan_calc.py.
    Credit staff get the amounts; sales staff only the fee tier that applies,
    since the amounts reveal the balance (credit-only)."""

    months = months_between(date.fromisoformat(contract["start_date"]), as_of)
    item = {"contract_id": contract["contract_id"], "months_since_start": months, "fee_rate": prepayment_fee_rate(months)}

    if role == "credit":
        remaining = remaining_balance(
            contract["principal"], contract["annual_rate"], contract["term_months"], contract["due_periods"],
            product_method(contract["product"]), contract["residual_value"],
        )
        quote = payoff_quote(remaining, contract["overdue_amount"], months)
        parts = {
            "remaining_principal": round(quote.remaining_principal),
            "overdue_amount": round(quote.overdue_amount),
            "fee": round(quote.fee),
        }
        # The total is the sum of the displayed (rounded) parts, so the line
        # always adds up on screen.
        item.update(parts, total=sum(parts.values()))
    return item


def build_view(customer: dict, contracts: list[dict], payments: list[dict], as_of: date, role: str, months: int,
               include_payoff: bool = False) -> dict:

    """The role-filtered, masked record -- the only customer data that ever
    leaves this module (to the LLM prompt, the reply and the audit log).
    include_payoff adds a 提前清償試算 per active contract (see build_payoff)."""

    late = compute_late_facts(payments, as_of)
    view = {
        "role": role,
        "as_of": as_of.isoformat(),
        "months": months,
        "customer": {
            "customer_id": customer["customer_id"],
            "name": customer["name"],
            "national_id": mask_national_id(customer["national_id"]),
            "phone": mask_phone(customer["phone"]),
            "customer_since": customer["customer_since"],
            "branch": customer["branch"],
        },
        "contracts": [],
    }

    for contract in contracts:
        item = {
            "contract_id": contract["contract_id"],
            "product": contract["product"],
            "vehicle": contract["vehicle"],
            "status": contract["status"],
            "term_months": contract["term_months"],
            "remaining_periods": contract["term_months"] - contract["paid_periods"],
        }
        if role == "credit":
            item["monthly_payment"] = contract["monthly_payment"]
            item["outstanding_balance"] = contract["outstanding_balance"]
        view["contracts"].append(item)

    if role == "credit":
        view["late"] = late
        view["customer"]["risk_note"] = customer["risk_note"]
    else:
        # Sales staff get one yes/no flag -- no counts, dates or amounts.
        view["late"] = {"has_late_record": late["late_count"] > 0 or late["currently_overdue"]}

    if include_payoff:
        view["payoff"] = [build_payoff(c, as_of, role) for c in contracts if c["status"] != "已結清"]

    return view


def render_facts(view: dict) -> str:

    """The facts block shown to the user, rendered by code so every number
    is exactly what the database holds."""

    customer = view["customer"]
    lines = [
        f"【客戶資料】{customer['name']}（{customer['customer_id']}）",
        f"- 身分證字號：{customer['national_id']}　電話：{customer['phone']}",
        f"- 往來起始：{customer['customer_since']}　所屬據點：{customer['branch']}",
        "【合約】",
    ]

    for c in view["contracts"]:
        line = f"- {c['contract_id']} {c['product']}／{c['vehicle']}：{c['status']}，期數 {c['term_months']}，剩餘 {c['remaining_periods']} 期"
        if "outstanding_balance" in c:
            line += f"，月付 NT${c['monthly_payment']:,}，未償餘額 NT${c['outstanding_balance']:,}"
        lines.append(line)
    if not view["contracts"]:
        lines.append("- 無合約紀錄")

    lines.append(f"【近{view['months']}個月繳款】")
    late = view["late"]
    if "has_late_record" in late:
        lines.append(f"- 近{view['months']}個月有逾期紀錄：{'有' if late['has_late_record'] else '無'}（詳情請洽授信人員）")
    else:
        lines.append(f"- 逾期次數：{late['late_count']}　最長逾期：{late['max_days_late']} 天")
        lines.append(f"- 目前逾期中：{'是，已逾期 ' + str(late['overdue_days']) + ' 天' if late['currently_overdue'] else '否'}")
        for p in late["late_periods"]:
            state = "已繳" if p["paid"] else "未繳"
            lines.append(f"  - {p['contract_id']} 第{p['period']}期（應繳日 {p['due_date']}）逾期 {p['days_late']} 天，{state}")
        lines.append(f"- 內部註記：{customer.get('risk_note') or '無'}")

    if "payoff" in view:
        lines.append(f"【提前清償試算】（依{PREPAYMENT_FEE_SOURCE}）")
        for p in view["payoff"]:
            tier = f"合約已滿 {p['months_since_start']} 個月，提前清償違約金費率 {p['fee_rate']:.0%}"
            if "total" in p:
                lines.append(f"- {p['contract_id']}：{tier}")
                lines.append(
                    f"  未到期本金 NT${p['remaining_principal']:,} ＋ 逾期未繳 NT${p['overdue_amount']:,} "
                    f"＋ 違約金 NT${p['fee']:,} ＝ 預估應付 NT${p['total']:,}"
                )
            else:
                lines.append(f"- {p['contract_id']}：{tier}；實際應付金額請洽授信人員。")
        if not view["payoff"]:
            lines.append("- 無進行中的合約")
        elif any("total" in p for p in view["payoff"]):
            lines.append("- 註：未含遲延利息，實際金額以授信部門結算為準。")

    return "\n".join(lines)


def render_candidates(customers: list[dict]) -> str:

    """Several customers share the name: list them masked, ask which one."""

    lines = ["查到多位同名客戶，請以客戶編號指定要查詢的對象："]
    for c in customers:
        lines.append(f"- {c['customer_id']} {c['name']}，身分證字號 {mask_national_id(c['national_id'])}，所屬據點 {c['branch']}")
    return "\n".join(lines)


def scope_line(role: str, as_of: str) -> str:

    return f"資料範圍：依「{ROLES[role]}」權限顯示，身分證字號與電話已遮罩；資料日期 {as_of}。"
